import type {
  SystemDashboardTab,
  SystemDashboardData,
  SystemDashboardResponse,
  DashboardChartResponse,
} from '~/client';
import { systemDashboard } from '~/client';

// The endpoint response is a union (chart dashboards + the payroll dashboard) keyed by tab.
// Callers pass the expected response type for their tab; chart pages keep the default.
export function useSystemDashboard<T extends SystemDashboardResponse = DashboardChartResponse>(
  tab: SystemDashboardTab,
  routeName: string
) {
  const route = useRoute();

  const defaultDate = computed(() => defaultDashboardDateRange());

  const params = computed(() => dashboardQueryParams<SystemDashboardData['query']>(route.query, defaultDate.value));

  const queryKey = computed(() => ['system.dashboard', tab, params.value]);

  const { data, error, isLoading } = useQuery({
    key: () => queryKey.value,
    query: () =>
      systemDashboard({
        composable: '$fetch',
        path: { tab },
        query: params,
      }) as Promise<T>,
    enabled: () => route.name === routeName,
  });

  return {
    data,
    error,
    isLoading,
    params,
    defaultDate,
    queryKey,
  };
}
